1	import { useState, useEffect } from "react";
2	import { FileText, Filter, ArrowLeft, Sun, Moon, Leaf, User as UserIcon, LogOut, ChevronLeft, ChevronRight, Search, X } from "lucide-react";
3	import { Input } from "@/shared/ui/input";
4	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/shared/ui/card";
5	import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
6	import { Badge } from "@/shared/ui/badge";
7	import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
8	import { supabase } from "@/integrations/supabase/client";
9	import { toast } from "@/shared/hooks/use-toast";
10	import { format } from "date-fns";
11	import { ptBR } from "date-fns/locale";
12	import { useStoreFilter } from "@/shared/hooks/useStoreData";
13	import { PermissionBlur } from "@/shared/ui/PermissionBlur";
14	import { usePermissions } from "@/shared/hooks/usePermissions";
15	import { useIsMobile } from "@/shared/hooks/use-mobile";
16	import { useTheme } from "next-themes";
17	import { useAuth } from "@/hooks/useAuth";
18	import { useStore } from "@/shared/contexts/StoreContext";
19	import { StoreSelector } from "@/shared/ui/StoreSelector";
20	import { useNavigate } from "react-router-dom";
21	import { cn } from "@/shared/lib/utils";
22	import { Button } from "@/shared/ui/button";
23	import { useMiaMovimentacoesActions } from '@/features/mia/model/hooks';
24	import {
25	  DropdownMenu,
26	  DropdownMenuContent,
27	  DropdownMenuItem,
28	  DropdownMenuLabel,
29	  DropdownMenuSeparator,
30	  DropdownMenuTrigger,
31	} from "@/shared/ui/dropdown-menu";
32	import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
33	
34	interface Movement {
35	  movimentacao_id: number;
36	  tipo_movimentacao: string;
37	  produto_nome: string;
38	  categoria_nome: string;
39	  categoria_emoji: string;
40	  quantidade: number;
41	  quantidade_anterior: number;
42	  quantidade_nova: number;
43	  unidade_medida: string;
44	  usuario_nome: string;
45	  data_movimentacao: string;
46	  motivo: string;
47	  observacoes: string;
48	  codigo_interno: number;
49	  lote_codigo?: string;
50	  lote_validade?: string;
51	}
52	
53	export default function Movimentacoes() {
54	  const [movements, setMovements] = useState<Movement[]>([]);
55	  const [isLoading, setIsLoading] = useState(true);
56	  const [sectorFilter, setSectorFilter] = useState<string>("todos");
57	  const [sectors, setSectors] = useState<string[]>([]);
58	  const [productSearch, setProductSearch] = useState<string>("");
59	  const { hasData, applyStoreFilter, storeId } = useStoreFilter();
60	  const { canViewEstoque, hasPermission, isAdmin } = usePermissions();
61	
62	  const isMobile = useIsMobile();
63	  const { theme, setTheme } = useTheme();
64	  const navigate = useNavigate();
65	  const { userProfile, user, signOut } = useAuth();
66	  const [serverVersion, setServerVersion] = useState<string | null>(null);
67	  const [currentPage, setCurrentPage] = useState(1);
68	  const ITEMS_PER_PAGE = 20;
69	
70	  useMiaMovimentacoesActions({
71	    setSectorFilter,
72	    setProductSearch,
73	    setCurrentPage,
74	    movements,
75	  });
76	
77	  useEffect(() => {
78	    if (hasData) {
79	      fetchSectors();
80	      fetchMovements();
81	    }
82	  }, [hasData, storeId]);
83	
84	  useEffect(() => {
85	    setCurrentPage(1);
86	    // fetchMovements will be called by the next useEffect because currentPage changes or we call it explicitly? 
87	    // Actually, if we setPage(1), and it was 1, it won't trigger. 
88	    // We should call fetchMovements() here if page is 1, or depend on currentPage
89	  }, [sectorFilter, productSearch]);
90	
91	  useEffect(() => {
92	    fetchMovements();
93	  }, [currentPage, sectorFilter, storeId, hasData, productSearch]);
94	
95	  useEffect(() => {
96	    if (isMobile) {
97	      fetch(`/version.json?t=${Date.now()}`)
98	        .then(res => res.json())
99	        .then(data => setServerVersion(data.version))
100	        .catch(err => console.error("Failed to fetch server version", err));
101	    }
102	  }, [isMobile]);
103	
104	  const fetchSectors = async () => {
105	    try {
106	      if (!hasData) {
107	        setSectors([]);
108	        return;
109	      }
110	
111	      // Use standard view for sectors
112	      // @ts-expect-error - supabase view type not in generated types
113	      const query = supabase
114	        .from('vw_produtos_estoque_lojas')
115	        .select('setor')
116	        .eq('loja_id', storeId) // Explicitly filter by store
117	        .not('setor', 'is', null);
118	
119	      // query = applyStoreFilter(query); // storeId is already applied above explicitly or via hook if passed, but let's be safe. 
120	      // applyStoreFilter uses the context storeId. If I use vw_produtos_estoque_lojas which has loja_id, it fits.
121	
122	      const { data, error } = await query;
123	
124	      if (error) throw error;
125	
126	      const uniqueSectors = [...new Set(data?.map((p: any) => p.setor) || [])]
127	        .filter(sector => sector && sector.toLowerCase() !== 'compras');
128	      setSectors(uniqueSectors as string[]);
129	    } catch (error) {
130	      console.error('Erro ao carregar setores:', error);
131	    }
132	  };
133	
134	  const fetchMovements = async () => {
135	    try {
136	      if (!hasData) {
137	        setMovements([]);
138	        return;
139	      }
140	
141	      const from = (currentPage - 1) * ITEMS_PER_PAGE;
142	      const to = from + ITEMS_PER_PAGE - 1;
143	
144	      // If there's a product search, prioritize it - search ALL movements without pagination
145	      if (productSearch.trim()) {
146	        const term = productSearch.trim();
147	        let searchQuery = supabase
148	          .from('view_movimentacoes_recentes')
149	          .select('*')
150	          .or(`produto_nome.ilike.%${term}%,codigo_interno_str.ilike.%${term}%,lote_codigo.ilike.%${term}%`)
151	          .order('data_movimentacao', { ascending: false })
152	          .limit(500); // High limit to get comprehensive results for the search
153	
154	        searchQuery = applyStoreFilter(searchQuery);
155	        const { data: searchData, error: searchError } = await searchQuery;
156	
157	        if (searchError) throw searchError;
158	        setMovements(searchData || []);
159	        return;
160	      }
161	
162	      if (sectorFilter !== "todos") {
163	        // Buscar produtos do setor - uses standard view
164	        // @ts-expect-error - supabase view type not in generated types
165	        const produtosQuery = supabase
166	          .from('vw_produtos_estoque_lojas')
167	          .select('produto_master_id, nome')
168	          .eq('loja_id', storeId)
169	          .eq('setor', sectorFilter);
170	
171	        const { data: produtos, error: produtosError } = await produtosQuery;
172	
173	        if (produtosError) throw produtosError;
174	
175	        if (produtos && produtos.length > 0) {
176	          const produtoNomes = produtos.map((p: any) => p.nome);
177	
178	          // Buscar movimentações filtrando pelo nome do produto
179	          let movQuery = supabase
180	            .from('view_movimentacoes_recentes')
181	            .select('*')
182	            .in('produto_nome', produtoNomes)
183	            .order('data_movimentacao', { ascending: false })
184	            .range(from, to);
185	
186	          movQuery = applyStoreFilter(movQuery);
187	          const { data: movData, error: movError } = await movQuery;
188	
189	          if (movError) throw movError;
190	          setMovements(movData || []);
191	        } else {
192	          setMovements([]);
193	        }
194	      } else {
195	        // Buscar todas as movimentações
196	        let allMovQuery = supabase
197	          .from('view_movimentacoes_recentes')
198	          .select('*')
199	          .order('data_movimentacao', { ascending: false })
200	          .range(from, to);
201	
202	        allMovQuery = applyStoreFilter(allMovQuery);
203	        const { data: allMovData, error: allMovError } = await allMovQuery;
204	
205	        if (allMovError) throw allMovError;
206	        setMovements(allMovData || []);
207	      }
208	    } catch (error) {
209	      console.error('Erro ao carregar movimentações:', error);
210	      toast({
211	        title: "Erro",
212	        description: "Não foi possível carregar as movimentações",
213	        variant: "destructive",
214	      });
215	    } finally {
216	      setIsLoading(false);
217	    }
218	  };
219	
220	  const getMovementColor = (type: string) => {
221	    return type === 'entrada' ? 'text-green-600' : 'text-red-600';
222	  };
223	
224	  const formatMovementType = (type: string) => {
225	    if (type === 'entrada') return 'Entrada';
226	    if (type === 'saida') return 'Saída';
227	    if (type === 'perda') return 'Perda';
228	    if (type === 'mudanca_categoria') return 'Mudança de categoria';
229	    if (type === 'cadastro') return 'Cadastro';
230	    if (type === 'exclusao') return 'Exclusão';
231	    return type;
232	  };
233	
234	  if (isLoading) {
235	    return (
236	      <div className="flex items-center justify-center min-h-screen">
237	        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary"></div>
238	      </div>
239	    );
240	  }
241	
242	  const hasAccess = hasPermission("view_movimentacoes") || canViewEstoque() || isAdmin();
243	
244	  if (isMobile) {
245	    return (
246	      <PermissionBlur hasPermission={hasAccess} moduleName="Estoque" permissionName="view_movimentacoes">
247	        <div className="flex flex-col min-h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans">
248	          {/* Store Awning Stripe Effect (Top Border) */}
249	          <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />
250	
251	          {/* Animated Plant Background Elements */}
252	          <div className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse" style={{ animationDuration: '10s' }}>
253	            <Leaf className="w-full h-full text-[#57715B] rotate-12" />
254	          </div>
255	
256	          {/* Header */}
257	          <div className="flex justify-between items-center px-6 pt-8 pb-2 z-20">
258	            <div className="flex items-center gap-3">
259	              <Button variant="ghost" size="icon" onClick={() => navigate(-1)} className="h-10 w-10 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10">
260	                <ArrowLeft className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
261	              </Button>
262	              <h1 className="text-xl font-bold text-[#57715B] dark:text-[#E6DCCF]">Movimentações</h1>
263	            </div>
264	            <div className="flex items-center gap-2">
265	              {/* Profile Menu with Store Selector and Theme Toggle */}
266	              <DropdownMenu>
267	                <DropdownMenuTrigger asChild>
268	                  <Button variant="ghost" className="h-10 w-10 rounded-full p-0 hover:bg-transparent relative">
269	                    <Avatar className="h-10 w-10 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md transition-transform active:scale-95">
270	                      <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-sm border border-[#C5A065]/20">
271	                        {(user?.user_metadata?.nome || "U").slice(0, 2).toUpperCase()}
272	                      </AvatarFallback>
273	                    </Avatar>
274	                  </Button>
275	                </DropdownMenuTrigger>
276	                <DropdownMenuContent className="w-64 rounded-2xl border-[#E6DCCF] dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xl" align="end" sideOffset={8}>
277	                  <DropdownMenuLabel className="font-normal p-4">
278	                    <div className="flex flex-col space-y-1">
279	                      <p className="text-base font-semibold leading-none text-[#57715B] dark:text-zinc-100">{user?.user_metadata?.nome || userProfile?.nome}</p>
280	                      <p className="text-xs text-zinc-500">{user?.email}</p>
281	                    </div>
282	                  </DropdownMenuLabel>
283	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
284	
285	                  {/* Store Selector inside Profile */}
286	                  <div className="px-2 py-2">
287	                    <div className="text-xs font-semibold text-muted-foreground px-2 mb-2">Loja</div>
288	                    <StoreSelector />
289	                  </div>
290	
291	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
292	
293	                  {/* Theme Toggle inside Profile */}
294	                  <div className="px-2 py-2 flex items-center justify-between">
295	                    <span className="text-sm font-medium px-2">Tema</span>
296	                    <Button
297	                      variant="ghost"
298	                      size="sm"
299	                      onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
300	                      className="h-8 w-8 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all"
301	                    >
302	                      <Sun className="h-4 w-4 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
303	                      <Moon className="absolute h-4 w-4 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
304	                    </Button>
305	                  </div>
306	
307	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
308	
309	                  {/* Version Indicator */}
310	                  <div className="px-2 py-1.5 text-[10px] text-center text-zinc-400 select-none">
311	                    v{String(typeof __APP_VERSION__ !== 'undefined' ? __APP_VERSION__ : '1.0.0')} / srv {serverVersion || '...'}
312	                  </div>
313	                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
314	                  <DropdownMenuItem
315	                    className="p-3 m-1 text-red-500 focus:text-red-600 focus:bg-red-50 dark:focus:bg-red-950/30 rounded-xl"
316	                    onClick={async () => {
317	                      await signOut();
318	                      toast({
319	                        title: "Até logo!",
320	                        description: "Você saiu com sucesso.",
321	                      });
322	                    }}
323	                  >
324	                    <LogOut className="mr-2 h-4 w-4" />
325	                    Sair
326	                  </DropdownMenuItem>
327	                </DropdownMenuContent>
328	              </DropdownMenu>
329	            </div>
330	          </div>
331	
332	          {/* Filters */}
333	          <div className="px-6 py-4 z-10 space-y-3">
334	            {/* Product Search Input */}
335	            <div className="relative">
336	              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400 pointer-events-none" />
337	              <Input data-mia-field="product_search"
338	                type="text"
339	                placeholder="Buscar produto pelo nome..."
340	                value={productSearch}
341	                onChange={(e) => setProductSearch(e.target.value)}
342	                className="pl-10 pr-10 h-10 rounded-2xl bg-white/60 dark:bg-zinc-900/60 border-[#57715B]/20 dark:border-white/10 focus-visible:ring-[#57715B]/30 focus-visible:border-[#57715B]/40"
343	              />
344	              {productSearch && (
345	                <Button
346	                  variant="ghost"
347	                  size="icon"
348	                  onClick={() => setProductSearch("")}
349	                  className="absolute right-1 top-1/2 -translate-y-1/2 h-8 w-8 rounded-full hover:bg-[#57715B]/10"
350	                >
351	                  <X className="h-4 w-4 text-zinc-400" />
352	                </Button>
353	              )}
354	            </div>
355	
356	            {/* Sector Filter Chips */}
357	            <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
358	              <Button
359	                variant={sectorFilter === 'todos' ? 'default' : 'outline'}
360	                onClick={() => setSectorFilter('todos')}
361	                disabled={!!productSearch}
362	                className={cn(
363	                  "rounded-full text-xs h-8 whitespace-nowrap transition-all",
364	                  sectorFilter === 'todos'
365	                    ? "bg-[#57715B] text-white hover:bg-[#57715B]/90 border-transparent"
366	                    : "border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/5 bg-transparent",
367	                  productSearch && "opacity-50"
368	                )}
369	              >
370	                Todos
371	              </Button>
372	              {sectors.map(sector => (
373	                <Button
374	                  key={sector}
375	                  variant={sectorFilter === sector ? 'default' : 'outline'}
376	                  onClick={() => setSectorFilter(sector)}
377	                  disabled={!!productSearch}
378	                  className={cn(
379	                    "rounded-full text-xs h-8 whitespace-nowrap transition-all",
380	                    sectorFilter === sector
381	                      ? "bg-[#57715B] text-white hover:bg-[#57715B]/90 border-transparent"
382	                      : "border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/5 bg-transparent",
383	                    productSearch && "opacity-50"
384	                  )}
385	                >
386	                  {sector}
387	                </Button>
388	              ))}
389	            </div>
390	          </div>
391	
392	          {/* List */}
393	          <div className="flex-1 px-6 pb-6 z-10 space-y-4">
394	            {movements.map((movement) => (
395	              <div key={movement.movimentacao_id} className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-md border border-[#57715B]/10 dark:border-white/5 rounded-2xl p-4 shadow-sm relative overflow-hidden transition-all active:scale-[0.98]">
396	                <div className="absolute top-0 right-0 p-3">
397	                  <span className="text-[10px] font-mono text-zinc-400">
398	                    {format(new Date(movement.data_movimentacao), 'dd/MM HH:mm', { locale: ptBR })}
399	                  </span>
400	                </div>
401	                <div className="flex items-start gap-3">
402	                  <span className="text-2xl mt-1 shrink-0">
403	                    {movement.categoria_emoji}
404	                  </span>
405	                  <div className="flex-1 min-w-0">
406	                    <h3 className="font-bold text-[#2D362E] dark:text-[#E6DCCF] text-sm line-clamp-1">{movement.produto_nome}</h3>
407	                    <p className="text-xs text-zinc-500 mb-2">{movement.categoria_nome}</p>
408	
409	                    {movement.lote_codigo && (
410	                      <div className="flex items-center gap-2 mb-1 flex-wrap">
411	                        <Badge variant="outline" className="text-[10px] h-5 px-1.5 border-[#57715B]/30 text-[#57715B] dark:text-[#E6DCCF] bg-[#57715B]/5">
412	                          Lote: {movement.lote_codigo}
413	                        </Badge>
414	                        {movement.lote_validade && (
415	                          <Badge variant="outline" className="text-[10px] h-5 px-1.5 border-zinc-300 text-zinc-500 bg-zinc-100/50 dark:bg-zinc-800/50 dark:border-zinc-700">
416	                            Val: {format(new Date(movement.lote_validade + 'T12:00:00'), 'dd/MM/yy', { locale: ptBR })}
417	                          </Badge>
418	                        )}
419	                      </div>
420	                    )}
421	
422	                    <div className="flex items-center justify-between mt-2">
423	                      <div className="flex items-center gap-1.5">
424	                        <Badge variant={movement.tipo_movimentacao === 'entrada' ? 'default' : 'destructive'} className="text-[10px] h-5 px-2">
425	                          {formatMovementType(movement.tipo_movimentacao)}
426	                        </Badge>
427	                        {(movement.motivo === 'scanner_lote' || movement.motivo === 'saida_inteira') && (
428	                          <Badge variant="outline" className="text-[10px] h-5 px-1.5 border-[#57715B]/30 text-[#57715B]/70 dark:text-[#E6DCCF]/70">
429	                            via Scanner
430	                          </Badge>
431	                        )}
432	                      </div>
433	                      <div className="flex items-center gap-1">
434	                        <span className={cn("font-mono font-bold text-sm", getMovementColor(movement.tipo_movimentacao))}>
435	                          {movement.tipo_movimentacao === 'entrada' ? '+' : '-'}{movement.quantidade}
436	                        </span>
437	                        <span className="text-xs text-zinc-400">{movement.unidade_medida}</span>
438	                      </div>
439	                    </div>
440	                  </div>
441	                </div>
442	                <div className="mt-3 pt-3 border-t border-dashed border-zinc-200 dark:border-zinc-800 flex items-center justify-between">
443	                  <div className="flex items-center gap-1.5 max-w-[50%]">
444	                    <UserIcon className="h-3 w-3 text-zinc-400 shrink-0" />
445	                    <span className="text-xs text-zinc-500 truncate">{movement.usuario_nome}</span>
446	                  </div>
447	                  <div className="flex items-center gap-1.5">
448	                    <span className="text-[10px] text-zinc-400">Ant: {movement.quantidade_anterior}</span>
449	                    <span className="text-[10px] text-zinc-300">→</span>
450	                    <span className="text-[10px] font-medium text-[#57715B] dark:text-[#8FA893]">Atual: {movement.quantidade_nova}</span>
451	                  </div>
452	                </div>
453	              </div>
454	            ))}
455	            {movements.length === 0 && (
456	              <div className="flex flex-col items-center justify-center py-12 text-center">
457	                <div className="h-16 w-16 rounded-full bg-[#E6DCCF]/30 flex items-center justify-center mb-4">
458	                  <FileText className="h-8 w-8 text-[#57715B]/40" />
459	                </div>
460	                <h3 className="text-lg font-medium text-[#2D362E] dark:text-[#E6DCCF]">Nenhuma movimentação</h3>
461	                <p className="text-sm text-zinc-500 max-w-[200px]">Não encontramos movimentações com os filtros atuais.</p>
462	              </div>
463	            )}
464	
465	            {/* Mobile Pagination - hidden when searching */}
466	            {!productSearch && (
467	              <div className="flex items-center justify-between pt-4 pb-8">
468	                <Button
469	                  variant="outline"
470	                  size="sm"
471	                  onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
472	                  disabled={currentPage === 1}
473	                  className="h-9 px-4 rounded-xl border-[#57715B]/20 dark:border-white/10"
474	                >
475	                  <ChevronLeft className="h-4 w-4 mr-2" />
476	                  Anterior
477	                </Button>
478	                <span className="text-sm font-medium text-zinc-500 underline decoration-dotted">
479	                  Página {currentPage}
480	                </span>
481	                <Button
482	                  variant="outline"
483	                  size="sm"
484	                  onClick={() => setCurrentPage(prev => prev + 1)}
485	                  disabled={movements.length < ITEMS_PER_PAGE}
486	                  className="h-9 px-4 rounded-xl border-[#57715B]/20 dark:border-white/10"
487	                >
488	                  Próxima
489	                  <ChevronRight className="h-4 w-4 ml-2" />
