import { useState, useEffect } from "react";
import { FileText, Filter, ArrowLeft, Sun, Moon, Leaf, User as UserIcon, LogOut, ChevronLeft, ChevronRight, Search, X } from "lucide-react";
import { Input } from "@/shared/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Badge } from "@/shared/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "@/shared/hooks/use-toast";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { useStoreFilter } from "@/shared/hooks/useStoreData";
import { PermissionBlur } from "@/shared/ui/PermissionBlur";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { useIsMobile } from "@/shared/hooks/use-mobile";
import { useTheme } from "next-themes";
import { useAuth } from "@/hooks/useAuth";
import { StoreSelector } from "@/shared/ui/StoreSelector";
import { useNavigate } from "react-router-dom";
import { cn } from "@/shared/lib/utils";
import { Button } from "@/shared/ui/button";
import { useMiaMovimentacoesActions } from '@/features/mia/model/hooks';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";

interface Movement {
  movimentacao_id: number;
  tipo_movimentacao: string;
  produto_nome: string;
  categoria_nome: string;
  categoria_emoji: string;
  quantidade: number;
  quantidade_anterior: number;
  quantidade_nova: number;
  unidade_medida: string;
  usuario_nome: string;
  data_movimentacao: string;
  motivo: string;
  observacoes: string;
  codigo_interno: number;
  lote_codigo?: string;
  lote_validade?: string;
}

const getRequisicaoText = (observacoes: string | undefined) => {
  if (!observacoes) return "Req. Saída";
  const match = observacoes.match(/Saída por requisição #(\d+)/);
  return match ? `Req #${match[1]}` : "Req. Saída";
};

export default function Movimentacoes() {
  const [movements, setMovements] = useState<Movement[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [sectorFilter, setSectorFilter] = useState<string>("todos");
  const [userFilter, setUserFilter] = useState<string>("todos");
  const [sectors, setSectors] = useState<string[]>([]);
  const [productSearch, setProductSearch] = useState<string>("");
  const { hasData, applyStoreFilter, storeId } = useStoreFilter();
  const { canViewEstoque, hasPermission, isAdmin } = usePermissions();

  const isMobile = useIsMobile();
  const { theme, setTheme } = useTheme();
  const navigate = useNavigate();
  const { userProfile, user, signOut } = useAuth();
  const [serverVersion, setServerVersion] = useState<string | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const ITEMS_PER_PAGE = 20;

  useMiaMovimentacoesActions({
    setSectorFilter,
    setProductSearch,
    setCurrentPage,
    movements,
  });

  useEffect(() => {
    if (hasData) {
      fetchSectors();
      fetchMovements();
    }
  }, [hasData, storeId]);

  useEffect(() => {
    setCurrentPage(1);
  }, [sectorFilter, productSearch, userFilter]);

  useEffect(() => {
    fetchMovements();
  }, [currentPage, sectorFilter, storeId, hasData, productSearch]);

  useEffect(() => {
    if (isMobile) {
      fetch(`/version.json?t=${Date.now()}`)
        .then(res => res.json())
        .then(data => setServerVersion(data.version))
        .catch(err => console.error("Failed to fetch server version", err));
    }
  }, [isMobile]);

  const fetchSectors = async () => {
    try {
      if (!hasData) {
        setSectors([]);
        return;
      }

      // Use standard view for sectors
      // @ts-expect-error - supabase view type not in generated types
      const query = supabase
        .from('vw_produtos_estoque_lojas')
        .select('setor')
        .eq('loja_id', storeId) // Explicitly filter by store
        .not('setor', 'is', null);

      const { data, error } = await query;

      if (error) throw error;

      const uniqueSectors = [...new Set(data?.map((p: any) => p.setor) || [])]
        .filter(sector => sector && sector.toLowerCase() !== 'compras');
      setSectors(uniqueSectors as string[]);
    } catch (error) {
      console.error('Erro ao carregar setores:', error);
    }
  };

  const fetchMovements = async () => {
    try {
      if (!hasData) {
        setMovements([]);
        return;
      }

      const from = (currentPage - 1) * ITEMS_PER_PAGE;
      const to = from + ITEMS_PER_PAGE - 1;

      // If there's a product search, prioritize it - search ALL movements without pagination
      if (productSearch.trim()) {
        const term = productSearch.trim();
        let searchQuery = supabase
          .from('view_movimentacoes_recentes')
          .select('*')
          .or(`produto_nome.ilike.%${term}%,codigo_interno_str.ilike.%${term}%,lote_codigo.ilike.%${term}%`)
          .order('data_movimentacao', { ascending: false })
          .limit(500); // High limit to get comprehensive results for the search

        searchQuery = applyStoreFilter(searchQuery);
        const { data: searchData, error: searchError } = await searchQuery;

        if (searchError) throw searchError;
        setMovements(searchData || []);
        return;
      }

      if (sectorFilter !== "todos") {
        // Buscar produtos do setor - uses standard view
        // @ts-expect-error - supabase view type not in generated types
        const produtosQuery = supabase
          .from('vw_produtos_estoque_lojas')
          .select('produto_master_id, nome')
          .eq('loja_id', storeId)
          .eq('setor', sectorFilter);

        const { data: produtos, error: produtosError } = await produtosQuery;

        if (produtosError) throw produtosError;

        if (produtos && produtos.length > 0) {
          const produtoNomes = produtos.map((p: any) => p.nome);

          // Buscar movimentações filtrando pelo nome do produto
          let movQuery = supabase
            .from('view_movimentacoes_recentes')
            .select('*')
            .in('produto_nome', produtoNomes)
            .order('data_movimentacao', { ascending: false })
            .range(from, to);

          movQuery = applyStoreFilter(movQuery);
          const { data: movData, error: movError } = await movQuery;

          if (movError) throw movError;
          setMovements(movData || []);
        } else {
          setMovements([]);
        }
      } else {
        // Buscar todas as movimentações
        let allMovQuery = supabase
          .from('view_movimentacoes_recentes')
          .select('*')
          .order('data_movimentacao', { ascending: false })
          .range(from, to);

        allMovQuery = applyStoreFilter(allMovQuery);
        const { data: allMovData, error: allMovError } = await allMovQuery;

        if (allMovError) throw allMovError;
        setMovements(allMovData || []);
      }
    } catch (error) {
      console.error('Erro ao carregar movimentações:', error);
      toast({
        title: "Erro",
        description: "Não foi possível carregar as movimentações",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const getMovementColor = (type: string) => {
    return type === 'entrada' ? 'text-green-600' : 'text-red-600';
  };

  const formatMovementType = (type: string) => {
    if (type === 'entrada') return 'Entrada';
    if (type === 'saida') return 'Saída';
    if (type === 'perda') return 'Perda';
    if (type === 'mudanca_categoria') return 'Mudança de categoria';
    if (type === 'cadastro') return 'Cadastro';
    if (type === 'exclusao') return 'Exclusão';
    return type;
  };

  const uniqueUsers = [...new Set(movements.map(m => m.usuario_nome))].filter(Boolean).sort();
  const filteredMovements = userFilter === 'todos' ? movements : movements.filter(m => m.usuario_nome === userFilter);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary"></div>
      </div>
    );
  }

  const hasAccess = hasPermission("view_movimentacoes") || canViewEstoque() || isAdmin();

  if (isMobile) {
    return (
      <PermissionBlur hasPermission={hasAccess} moduleName="Estoque" permissionName="view_movimentacoes">
        <div className="flex flex-col min-h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-x-hidden relative font-sans">
          {/* Store Awning Stripe Effect (Top Border) */}
          <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />

          {/* Animated Plant Background Elements */}
          <div className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse" style={{ animationDuration: '10s' }}>
            <Leaf className="w-full h-full text-[#57715B] rotate-12" />
          </div>

          {/* Header */}
          <div className="flex justify-between items-center px-6 pt-8 pb-2 z-20">
            <div className="flex items-center gap-3">
              <Button variant="ghost" size="icon" onClick={() => navigate(-1)} className="h-10 w-10 -ml-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10">
                <ArrowLeft className="h-6 w-6 text-[#57715B] dark:text-[#E6DCCF]" />
              </Button>
              <h1 className="text-xl font-bold text-[#57715B] dark:text-[#E6DCCF]">Movimentações</h1>
            </div>
            <div className="flex items-center gap-2">
              {/* Profile Menu with Store Selector and Theme Toggle */}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" className="h-10 w-10 rounded-full p-0 hover:bg-transparent relative">
                    <Avatar className="h-10 w-10 ring-2 ring-[#E6DCCF] dark:ring-zinc-700 shadow-md transition-transform active:scale-95">
                      <AvatarFallback className="bg-[#E6DCCF] text-[#57715B] font-bold text-sm border border-[#C5A065]/20">
                        {(user?.user_metadata?.nome || "U").slice(0, 2).toUpperCase()}
                      </AvatarFallback>
                    </Avatar>
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent className="w-64 rounded-2xl border-[#E6DCCF] dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xl" align="end" sideOffset={8}>
                  <DropdownMenuLabel className="font-normal p-4">
                    <div className="flex flex-col space-y-1">
                      <p className="text-base font-semibold leading-none text-[#57715B] dark:text-zinc-100">{user?.user_metadata?.nome || userProfile?.nome}</p>
                      <p className="text-xs text-zinc-500">{user?.email}</p>
                    </div>
                  </DropdownMenuLabel>
                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />

                  {/* Store Selector inside Profile */}
                  <div className="px-2 py-2">
                    <div className="text-xs font-semibold text-muted-foreground px-2 mb-2">Loja</div>
                    <StoreSelector />
                  </div>

                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />

                  {/* Theme Toggle inside Profile */}
                  <div className="px-2 py-2 flex items-center justify-between">
                    <span className="text-sm font-medium px-2">Tema</span>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
                      className="h-8 w-8 rounded-full bg-[#E6DCCF]/40 dark:bg-white/10 border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/10 transition-all"
                    >
                      <Sun className="h-4 w-4 text-[#57715B] dark:text-[#8FA893] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
                      <Moon className="absolute h-4 w-4 text-[#8FA893] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
                    </Button>
                  </div>

                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />

                  {/* Version Indicator */}
                  <div className="px-2 py-1.5 text-[10px] text-center text-zinc-400 select-none">
                    v{String(typeof __APP_VERSION__ !== 'undefined' ? __APP_VERSION__ : '1.0.0')} / srv {serverVersion || '...'}
                  </div>
                  <DropdownMenuSeparator className="bg-[#E6DCCF] dark:bg-zinc-800" />
                  <DropdownMenuItem
                    className="p-3 m-1 text-red-500 focus:text-red-600 focus:bg-red-50 dark:focus:bg-red-950/30 rounded-xl"
                    onClick={async () => {
                      await signOut();
                      toast({
                        title: "Até logo!",
                        description: "Você saiu com sucesso.",
                      });
                    }}
                  >
                    <LogOut className="mr-2 h-4 w-4" />
                    Sair
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          </div>

          {/* Filters */}
          <div className="px-6 py-4 z-10 space-y-3">
            {/* Product Search Input */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-zinc-400 pointer-events-none" />
              <Input data-mia-field="product_search"
                type="text"
                placeholder="Buscar produto pelo nome..."
                value={productSearch}
                onChange={(e) => setProductSearch(e.target.value)}
                className="pl-10 pr-10 h-10 rounded-2xl bg-white/60 dark:bg-zinc-900/60 border-[#57715B]/20 dark:border-white/10 focus-visible:ring-[#57715B]/30 focus-visible:border-[#57715B]/40"
              />
              {productSearch && (
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setProductSearch("")}
                  className="absolute right-1 top-1/2 -translate-y-1/2 h-8 w-8 rounded-full hover:bg-[#57715B]/10"
                >
                  <X className="h-4 w-4 text-zinc-400" />
                </Button>
              )}
            </div>

            {/* Sector Filter Chips */}
            <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
              <Button
                variant={sectorFilter === 'todos' ? 'default' : 'outline'}
                onClick={() => setSectorFilter('todos')}
                disabled={!!productSearch}
                className={cn(
                  "rounded-full text-xs h-8 whitespace-nowrap transition-all",
                  sectorFilter === 'todos'
                    ? "bg-[#57715B] text-white hover:bg-[#57715B]/90 border-transparent"
                    : "border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/5 bg-transparent",
                  productSearch && "opacity-50"
                )}
              >
                Todos Setores
              </Button>
              {sectors.map(sector => (
                <Button
                  key={sector}
                  variant={sectorFilter === sector ? 'default' : 'outline'}
                  onClick={() => setSectorFilter(sector)}
                  disabled={!!productSearch}
                  className={cn(
                    "rounded-full text-xs h-8 whitespace-nowrap transition-all",
                    sectorFilter === sector
                      ? "bg-[#57715B] text-white hover:bg-[#57715B]/90 border-transparent"
                      : "border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/5 bg-transparent",
                    productSearch && "opacity-50"
                  )}
                >
                  {sector}
                </Button>
              ))}
            </div>

            {/* User Filter Chips */}
            {uniqueUsers.length > 0 && (
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                <Button
                  variant={userFilter === 'todos' ? 'default' : 'outline'}
                  onClick={() => setUserFilter('todos')}
                  className={cn(
                    "rounded-full text-xs h-8 whitespace-nowrap transition-all",
                    userFilter === 'todos'
                      ? "bg-[#57715B] text-white hover:bg-[#57715B]/90 border-transparent"
                      : "border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/5 bg-transparent",
                  )}
                >
                  Todos Operadores
                </Button>
                {uniqueUsers.map(u => (
                  <Button
                    key={u}
                    variant={userFilter === u ? 'default' : 'outline'}
                    onClick={() => setUserFilter(u)}
                    className={cn(
                      "rounded-full text-xs h-8 whitespace-nowrap transition-all",
                      userFilter === u
                        ? "bg-[#57715B] text-white hover:bg-[#57715B]/90 border-transparent"
                        : "border-[#57715B]/20 text-[#57715B] dark:text-[#E6DCCF] hover:bg-[#57715B]/5 bg-transparent",
                    )}
                  >
                    {u}
                  </Button>
                ))}
              </div>
            )}
          </div>

          {/* List */}
          <div className="flex-1 px-6 pb-6 z-10 space-y-4">
            {filteredMovements.map((movement) => (
              <div key={movement.movimentacao_id} className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-md border border-[#57715B]/10 dark:border-white/5 rounded-2xl p-4 shadow-sm relative overflow-hidden transition-all active:scale-[0.98]">
                <div className="absolute top-0 right-0 p-3">
                  <span className="text-[10px] font-mono text-zinc-400">
                    {format(new Date(movement.data_movimentacao), 'dd/MM HH:mm', { locale: ptBR })}
                  </span>
                </div>
                <div className="flex items-start gap-3">
                  <span className="text-2xl mt-1 shrink-0">
                    {movement.categoria_emoji}
                  </span>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-bold text-[#2D362E] dark:text-[#E6DCCF] text-sm line-clamp-1">{movement.produto_nome}</h3>
                    <p className="text-xs text-zinc-500 mb-2">{movement.categoria_nome}</p>

