import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/shared/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/shared/ui/table";
import { Skeleton } from "@/shared/ui/skeleton";
import { Button } from "@/shared/ui/button";
import { PackageCheck, PackageX } from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

interface Props {
  requisicaoId: number;
  open: boolean;
  onClose: () => void;
}

interface SaidaItem {
  etiqueta_uid: string;
  usuario_nome: string | null;
  metadata: {
    lote_id?: string;
    quantidade?: number;
    saldo_anterior?: number;
    saldo_novo?: number;
  };
  created_at: string;
  produto_nome_snapshot: string | null;
}

export function SaidaRequisicaoResumoDialog({ requisicaoId, open, onClose }: Props) {
  const { data: itens, isLoading } = useQuery<SaidaItem[]>({
    queryKey: ['saida-requisicao-eventos', requisicaoId],
    enabled: open && requisicaoId > 0,
    queryFn: async () => {
      // 1. Fetch events
      const { data: eventos, error: eventosError } = await (supabase.from('etiquetas_qr_eventos') as any)
        .select('etiqueta_uid, usuario_nome, metadata, created_at')
        .eq('tipo_evento', 'saida_requisicao')
        .eq('referencia_tipo', 'requisicao')
        .eq('referencia_id', String(requisicaoId));

      if (eventosError) throw eventosError;

      if (!eventos || eventos.length === 0) {
        return [];
      }

      const uids = [...new Set(eventos.map((e: any) => e.etiqueta_uid as string))];

      // 2. Fetch tags
      const { data: tags, error: tagsError } = await (supabase.from('etiquetas_qr') as any)
        .select('uid, produto_nome_snapshot')
        .in('uid', uids);

      if (tagsError) throw tagsError;

      const tagsMap = new Map<string, string | null>(
        (tags || []).map((t: any) => [t.uid as string, t.produto_nome_snapshot as string | null])
      );

      // 3. Join
      return eventos.map((e: any) => ({
        etiqueta_uid: e.etiqueta_uid as string,
        usuario_nome: e.usuario_nome as string | null,
        metadata: (e.metadata || {}) as SaidaItem['metadata'],
        created_at: e.created_at as string,
        produto_nome_snapshot: tagsMap.get(e.etiqueta_uid as string) ?? null,
      })) as SaidaItem[];
    }
  });

  const totalItens = itens?.length || 0;
  const totalQuantidade = itens?.reduce((acc, curr) => acc + (curr.metadata?.quantidade || 0), 0) || 0;

  return (
    <Dialog open={open} onOpenChange={(val) => !val && onClose()}>
      <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl max-w-2xl p-0 overflow-hidden">
        <DialogHeader className="p-6 pb-4 border-b border-[#57715B]/10">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-[#57715B]/10 flex items-center justify-center">
              <PackageCheck className="h-5 w-5 text-[#57715B]" />
            </div>
            <DialogTitle className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              Saída por Requisição #{requisicaoId}
            </DialogTitle>
          </div>
        </DialogHeader>

        <div className="p-6">
          {isLoading ? (
            <div className="space-y-3">
              <Skeleton className="h-10 w-full rounded-xl bg-[#57715B]/5" />
              <Skeleton className="h-10 w-full rounded-xl bg-[#57715B]/5" />
              <Skeleton className="h-10 w-full rounded-xl bg-[#57715B]/5" />
            </div>
          ) : !itens || itens.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-center">
              <div className="h-16 w-16 rounded-full bg-[#57715B]/5 flex items-center justify-center mb-4">
                <PackageX className="h-8 w-8 text-[#57715B]/40" />
              </div>
              <h3 className="text-lg font-medium text-[#2D362E] dark:text-[#E6DCCF]">Nenhuma saída registrada</h3>
              <p className="text-sm text-muted-foreground mt-1">
                Nenhuma saída foi registrada para esta requisição.
              </p>
            </div>
          ) : (
            <div className="space-y-4">
              {/* Summary Bar */}
              <div className="flex items-center gap-4 p-4 rounded-xl bg-[#57715B]/5 border border-[#57715B]/10">
                <div>
                  <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Total de Itens</div>
                  <div className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">{totalItens}</div>
                </div>
                <div className="w-px h-8 bg-[#57715B]/10" />
                <div>
                  <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Quantidade Total</div>
                  <div className="text-lg font-bold text-[#57715B]">{totalQuantidade}</div>
                </div>
              </div>

              {/* Table */}
              <div className="rounded-xl border border-[#57715B]/10 overflow-hidden">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader className="bg-[#57715B]/5 border-b border-[#57715B]/10">
                      <TableRow className="hover:bg-transparent">
                        <TableHead className="font-semibold text-[#57715B]">Produto</TableHead>
                        <TableHead className="font-semibold text-[#57715B]">Lote</TableHead>
                        <TableHead className="font-semibold text-[#57715B] text-center">Qtd</TableHead>
                        <TableHead className="font-semibold text-[#57715B]">Operador</TableHead>
                        <TableHead className="font-semibold text-[#57715B] text-right">Horário</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {itens.map((item, idx) => (
                        <TableRow
                          key={`${item.etiqueta_uid}-${idx}`}
                          className="hover:bg-[#57715B]/5 border-b border-[#57715B]/5 last:border-0 transition-colors"
                        >
                          <TableCell className="font-medium text-[#2D362E] dark:text-[#E6DCCF]">
                            {item.produto_nome_snapshot || 'Produto Desconhecido'}
                          </TableCell>
                          <TableCell>
                            {item.metadata?.lote_id ? (
                              <span className="font-mono text-xs text-muted-foreground bg-white/50 dark:bg-black/20 px-2 py-1 rounded-md border border-[#57715B]/10">
                                {item.metadata.lote_id.substring(0, 8)}
                              </span>
                            ) : (
                              <span className="text-xs text-muted-foreground italic">N/A</span>
                            )}
                          </TableCell>
                          <TableCell className="text-center font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                            {item.metadata?.quantidade ?? 0}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {item.usuario_nome || 'Desconhecido'}
                          </TableCell>
                          <TableCell className="text-right font-mono text-xs text-muted-foreground">
                            {format(new Date(item.created_at), 'dd/MM HH:mm', { locale: ptBR })}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="p-4 border-t border-[#57715B]/10 flex justify-end bg-white/50 dark:bg-black/20">
          <Button variant="ghost" onClick={onClose} className="text-[#57715B] hover:bg-[#57715B]/10">
            Fechar
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
